function env(name) {
  try { return String($env[name] || '').trim(); } catch (error) { return ''; }
}
function readHeader(headers, name) {
  const target = name.toLowerCase();
  for (const [key, value] of Object.entries(headers || {})) {
    if (String(key).toLowerCase() === target) return Array.isArray(value) ? value[0] : value;
  }
  return '';
}
function safeEqual(left, right) {
  const a = String(left || '');
  const b = String(right || '');
  if (!a || a.length !== b.length) return false;
  let difference = 0;
  for (let index = 0; index < a.length; index += 1) difference |= a.charCodeAt(index) ^ b.charCodeAt(index);
  return difference === 0;
}
function reject(statusCode, code, message) {
  return [{ json: { request_valid: false, statusCode, body: { code, message } } }];
}

const request = $input.first().json || {};
const headers = request.headers || {};
const expectedToken = env('RENOV_INTERNAL_TOKEN');
const runnerToken = env('RENOV_E2E_RUNNER_TOKEN');
const runnerBase = env('RENOV_E2E_RUNNER_URL').replace(/\/+$/, '');

if (!expectedToken || !runnerToken || !runnerBase) {
  return reject(503, 'CONFIG_ERROR', 'La orquestación E2E no está configurada.');
}

const baseMatch = runnerBase.match(/^https?:\/\/[a-z0-9._-]+(?::([0-9]{1,5}))?$/i);
if (!baseMatch || (baseMatch[1] && Number(baseMatch[1]) > 65535)) {
  return reject(503, 'CONFIG_ERROR', 'RENOV_E2E_RUNNER_URL no es una base URL válida.');
}

const authorization = String(readHeader(headers, 'authorization') || '');
const providedToken = readHeader(headers, 'x-internal-token')
  || (/^Bearer\s+/i.test(authorization) ? authorization.replace(/^Bearer\s+/i, '').trim() : '');
if (!safeEqual(providedToken, expectedToken)) {
  return reject(401, 'UNAUTHORIZED', 'Token interno inválido o ausente.');
}

const pathname = String(request.webhookUrl || '').split(/[?#]/, 1)[0].replace(/\/+$/, '');
const operations = {
  '/session-status': { operation: 'session_status', method: 'GET', path: '/session/status', fixture: true },
  '/session-qr': { operation: 'session_qr', method: 'POST', path: '/session/qr', fixture: true },
  '/run': { operation: 'run', method: 'POST', path: '/runs', fixture: true },
};

let route = Object.entries(operations).find(([suffix]) => pathname.endsWith(suffix))?.[1] || null;
if (pathname.endsWith('/run-status')) {
  const runId = String(request.query?.runId ?? request.query?.run_id ?? '').trim();
  if (!runId) return reject(422, 'MISSING_REQUIRED_FIELD', 'Indique runId.');
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(runId)) {
    return reject(422, 'INVALID_RUN_ID', 'runId debe ser un UUID.');
  }
  route = { operation: 'run_status', method: 'GET', path: '/runs/' + encodeURIComponent(runId) };
}
if (!route) return reject(404, 'NOT_FOUND', 'Operación E2E desconocida.');
let fixtureSlot = null;
if (route.fixture) {
  fixtureSlot = Number(request.query?.fixtureSlot ?? request.query?.fixture_slot ?? 0);
  if (!Number.isInteger(fixtureSlot) || fixtureSlot < 1 || fixtureSlot > 3) {
    return reject(422, 'INVALID_FIXTURE_SLOT', 'fixtureSlot debe ser 1, 2 o 3.');
  }
}

return [{ json: {
  request_valid: true,
  statusCode: 200,
  operation: route.operation,
  runner_method: route.method,
  fixture_slot: fixtureSlot,
  runner_url: runnerBase + route.path + (fixtureSlot ? '?fixtureSlot=' + fixtureSlot : ''),
} }];

const response = $input.first().json || {};
const statusCode = Number(response.statusCode ?? response.status ?? 0);
if (!Number.isInteger(statusCode) || statusCode < 100 || statusCode > 599) {
  return [{ json: {
    statusCode: 502,
    body: { code: 'E2E_RUNNER_UNAVAILABLE', message: 'El runner Playwright no respondió.' },
  } }];
}

const body = response.body;
if (!body || typeof body !== 'object' || Array.isArray(body)) {
  return [{ json: {
    statusCode: 502,
    body: { code: 'E2E_RUNNER_INVALID_RESPONSE', message: 'El runner Playwright devolvió una respuesta inválida.' },
  } }];
}

return [{ json: { statusCode, body } }];
